def compute(vars):
    decrease = vars["v1"]
    net_revenue_2003 = vars["v2"]
    if net_revenue_2003 == 0:
        return {
            "value": None,
            "trace": {
                "decrease_in_gross_wholesale_revenue": decrease,
                "net_revenue_2003": net_revenue_2003,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage"
                }
            }
        }

    percentage = (decrease / net_revenue_2003) * 100
    return {
        "value": percentage,
        "trace": {
            "decrease_in_gross_wholesale_revenue": decrease,
            "net_revenue_2003": net_revenue_2003,
            "calculation": "(v1 / v2) * 100",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
